package com.lolfm.simulator;import static org.assertj.core.api.Assertions.*;import com.lolfm.factory.DummyDataFactory;import org.junit.jupiter.api.Test;class ProgressionFeatureToggleTest{private MatchSimulator sim(SimulationOptions o){return new MatchSimulator(new TeamfightResolver(),new EndGameEvaluator(),new SnapshotFactory(),new ObjectiveResolver(),new PostFightResolver(),new ObjectiveAttemptResolver(),new StructureResolver(),new PushResolver(),o);}@Test void progressionOffKeepsNeutralStateAndPower(){var f=new DummyDataFactory();var t=sim(SimulationOptions.productionDefaults().withProgressionEnabled(false)).simulate(f.createBlueTeam(),f.createRedTeam(),7);var end=t.getSnapshots().getLast();assertThat(end.getProgression().enabled()).isFalse();assertThat(end.getPlayerSnapshots()).allMatch(p->p.getLevel()==1&&p.getTotalExperience()==0&&p.getProgressionEarnedGold()==0&&p.getProgressionPower().totalPower()==0);}@Test void stateOnPowerOffProgressesWithZeroPower(){var f=new DummyDataFactory();var t=sim(SimulationOptions.productionDefaults().withProgressionPowerEnabled(false)).simulate(f.createBlueTeam(),f.createRedTeam(),7);var end=t.getSnapshots().getLast();assertThat(end.getProgression().powerEnabled()).isFalse();assertThat(end.getPlayerSnapshots()).anyMatch(p->p.getLevel()>1);assertThat(end.getPlayerSnapshots()).allMatch(p->p.getProgressionPower().totalPower()==0);}@Test void disablingProgressionForcesPowerOff(){assertThat(SimulationOptions.productionDefaults().withProgressionEnabled(false).withProgressionPowerEnabled(true).progressionPowerEnabled()).isFalse();}}
